export const getBaseTitle = (productOrTitle = "") => {
    if (typeof productOrTitle === "object" && productOrTitle) return productOrTitle.title || "";
    return String(productOrTitle).split("|")[0].trim();
};

export const getProductColor = (productOrTitle = "") => {
    if (typeof productOrTitle === "object" && productOrTitle) return productOrTitle.color || "Default";
    const parts = String(productOrTitle).split("|").map((part) => part.trim());
    return parts[1] || "Default";
};

export const getProductVariants = (product) => {
    if (!product) return [];
    return Array.isArray(product.variants) && product.variants.length ? product.variants : [product];
};

